function renderArithmetic(spec){const ops={subtract:'\u2212',add:'+',multiply:'\u00d7',divide:'\u00f7'},op=String(spec?.operation||'subtract').toLowerCase(),items=(Array.isArray(spec?.items)?spec.items:[]).slice(0,200),cols=Math.max(1,Math.min(8,Math.trunc(num(spec?.columns,4))||4));if(!ops[op]||!items.length)throw Error('Invalid arithmetic.');const h=(tag,cls,val)=>{const n=document.createElement(tag);n.className=cls;if(val!==undefined)n.textContent=val;return n},box=h('div','edu-arith'),grid=h('div','edu-arith-grid');grid.style.setProperty('--arith-cols',cols);items.forEach(p=>{if(!Array.isArray(p)||p.length!==2||!p.every(v=>Number.isFinite(Number(v))))throw Error('Invalid item.');const cell=h('div','edu-arith-item'),bottom=h('div','edu-arith-bottom');bottom.append(h('span','edu-arith-sign',ops[op]),h('span','',String(+p[1])));cell.append(h('div','edu-arith-top',String(+p[0])),bottom,h('div','edu-arith-rule'),h('div','edu-arith-answer',' '));grid.appendChild(cell)});box.appendChild(grid);return box}
async function renderMath(spec){const m=await import('./tex-math.js'),box=document.createElement('div');box.className='edu-math-render';if(spec.title){const h=document.createElement('div');h.className='edu-title';h.textContent=text(spec.title,160);box.appendChild(h)}const result=m.renderTeXMath(String(spec.tex||''),{display:spec.display!==false});if(!result)throw Error('Matematický zápis je prázdný.');box.appendChild(result);if(spec.verify){const cas=await import('./school-cas.js'),v=cas.casVerify(spec.verify);if(!v.ok)throw Error('CAS ověření neprošlo: '+text(v.message||'neplatný výsledek',140));box.dataset.casVerified='1'}return box}
function renderOffice(spec){const svg=svgBase(720,420),W=Math.max(1,num(spec.width,12192000)),H=Math.max(1,num(spec.height,6858000)),sx=660/W,sy=350/H;title(svg,spec);const ox=30,oy=45,shapes=(Array.isArray(spec.shapes)?spec.shapes:[]).slice(0,180);if(!shapes.length)throw Error('Office objekt neobsahuje rekonstruovatelné tvary.');for(const sh of shapes){const x=ox+num(sh.x)*sx,y=oy+num(sh.y)*sy,w=Math.max(2,num(sh.w)*sx),h=Math.max(2,num(sh.h)*sy),t=String(sh.type||'rect').toLowerCase(),cls='edu-office-shape';let n;if(sh.kind==='connector'||/line|connector/.test(t)){n=el('line',{x1:x,y1:y,x2:x+w,y2:y+h,class:cls})}else if(/ellipse|oval/.test(t)){n=el('ellipse',{cx:x+w/2,cy:y+h/2,rx:w/2,ry:h/2,class:cls})}else if(/triangle/.test(t)){n=el('polygon',{points:`${x+w/2},${y} ${x+w},${y+h} ${x},${y+h}`,class:cls})}else if(/diamond/.test(t)){n=el('polygon',{points:`${x+w/2},${y} ${x+w},${y+h/2} ${x+w/2},${y+h} ${x},${y+h/2}`,class:cls})}else if(/hexagon/.test(t)){n=el('polygon',{points:`${x+w*.25},${y} ${x+w*.75},${y} ${x+w},${y+h/2} ${x+w*.75},${y+h} ${x+w*.25},${y+h} ${x},${y+h/2}`,class:cls})}else{n=el('rect',{x,y,width:w,height:h,rx:/roundrect|round/.test(t)?Math.min(12,w/5,h/5):0,class:cls})}svg.appendChild(n);if(sh.text)label(svg,x+w/2,y+h/2+5,text(sh.text,80),'middle','edu-office-label')}return svg}
function caption(fig,spec,kind){if(kind==='arith'&&!String(spec&&spec.caption||spec&&spec.title||'').trim()){const old=fig.querySelector('figcaption');if(old)old.remove();return}let c=fig.querySelector('figcaption');if(!c){c=document.createElement('figcaption');fig.appendChild(c)}c.textContent=text(spec.caption||spec.title||({chart:'Datový graf',coord:'Souřadnicový nákres',music:'Notový zápis',chem:'Chemická struktura',map:'Slepá mapa',circuit:'Elektrické schéma',math:'Matematický zápis',arith:'Písemná aritmetika',office:'Office schéma',flow:'Diagram vztahů',timeline:'Časová osa',genetics:'Genetický diagram',phys:'Fyzikální diagram',trace:'Algoritmická stopa',reaction:'Chemická reakce',annotate:'Anotovaný obraz'})[kind]||'Odborný vizuál',180)}
async function hydrateOne(fig){if(!fig||fig.dataset.eduReady==='1')return;let spec;try{spec=JSON.parse(fig.dataset.eduSpec||'{}')}catch(_){fig.dataset.eduReady='error';fig.textContent='Odborný vizuál nelze vykreslit: neplatná data.';return}const kind=String(fig.dataset.eduKind||'').toLowerCase();try{let svg;if(kind==='chart')svg=renderChart(spec);else if(kind==='coord')svg=renderCoord(spec);else if(kind==='music')svg=renderMusic(spec);else if(kind==='chem')svg=await renderChem(spec);else if(kind==='map')svg=await renderMap(spec);else if(kind==='circuit')svg=renderCircuit(spec);else if(kind==='math')svg=await renderMath(spec);else if(kind==='arith')svg=renderArithmetic(spec);else if(kind==='office')svg=renderOffice(spec);else if(kind==='flow')svg=await renderFlow(spec);else if(kind==='timeline')svg=await renderTimeline(spec);else if(kind==='genetics')svg=await renderGenetics(spec);else if(kind==='phys')svg=await renderPhysics(spec);else if(kind==='trace')svg=await renderTrace(spec);else if(kind==='reaction')svg=await renderReaction(spec);else if(kind==='annotate')svg=await renderAnnotate(spec,fig);else throw Error('Neznámý renderer.');fig.replaceChildren(svg);caption(fig,spec,kind);fig.dataset.eduReady='1'}catch(e){fig.dataset.eduReady='error';fig.textContent='Odborný vizuál nelze vykreslit: '+text(e&&e.message||'neplatná data',160)}}
export async function hydrateEducationalVisuals(root=document){const list=[];if(root&&root.matches&&root.matches('figure.edu-visual[data-edu-kind]'))list.push(root);if(root&&root.querySelectorAll)list.push(...root.querySelectorAll('figure.edu-visual[data-edu-kind]'));await Promise.all(list.filter(x=>x.dataset.eduReady!=='1').map(hydrateOne))}
